steps.code:
{% for group in robots.default_groups %}
  {%- for rule in group.rules -%}
    {{ rule }}
  {%- endfor -%}

  {%- if group.user_agent.value == '*' -%}
    Disallow: /*?q=*
  {%- endif -%}

  Sitemap: {{ sitemap }}
{% endfor %}

{% for rule in group.rules %}
  {% unless rule.directive == 'Disallow' and rule.value == '/some-path' %}
    {{ rule }}
  {% endunless %}
{% endfor %}

{% for group in robots.default_groups %}
  {%- for rule in group.rules -%}{{ rule }}{%- endfor -%}
  Sitemap: {{ sitemap }}
{% endfor %}
